```sql
/* Buffets and coffee shops open between 07:30 and 16:00 */
SELECT
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE (
        LOWER(r."service_format") LIKE '%buffet%'
        OR LOWER(r."service_format") LIKE '%coffee%'
        OR LOWER(r."name") LIKE '%coffee%'
      )
  /* Ensure the opening time is not later than 07:30 and closing time not earlier than 16:00 */
  AND (
        /* Extract opening time from hours text and compare */
        (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1] IS NOT NULL
        AND (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1]::time <= TIME '07:30'
      )
  AND (
        /* Extract closing time (last time in the string) and compare */
        (regexp_matches(r."hours", '(\d{1,2}:\d{2})', 'g'))[1] IS NOT NULL
        AND (
              SELECT MAX(m[1]::time)
              FROM regexp_matches(r."hours", '(\d{1,2}:\d{2})', 'g') AS m
            ) >= TIME '16:00'
      )
ORDER BY r."name";
```

