/* Выбираем заведения (буфеты и кофейни), работающие в интервале 07:30–16:00 */
SELECT
    r."id",
    r."name",
    r."address",
    r."service_format",
    r."hours"
FROM "restaurant" AS r
WHERE (
        /* Буфеты */
        LOWER(r."service_format") LIKE '%buffet%'
        /* Кофейни */
        OR LOWER(r."service_format") LIKE '%coffee%'
      )
  /* Проверяем, что время открытия не позже 07:30 и время закрытия не раньше 16:00 */
  AND (
        /* Извлекаем время открытия и закрытия из текстового поля hours */
        (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1]::time <= TIME '07:30'
        AND
        (regexp_match(r."hours", '.*?(\d{1,2}:\d{2})'))[1]::time >= TIME '16:00'
      )
ORDER BY r."name";
